8	/**
9	 * `self/` and `.github/` do not drift apart.
10	 *
11	 * ## What this replaced
12	 *
13	 * `.github/` used to be the release archive extracted over the previous contents,
14	 * with three files kept alive by remembering to run `git checkout --` on them
15	 * afterwards. Two things went wrong with that, and both were silent:
16	 *
17	 * - a file the upstream release had **deleted** stayed in the tree. `unzip -o`
18	 *   overwrites and never removes, so there was no diff to notice it by. The old
19	 *   `conventions.md` said to "look for orphans under `.github/atomaton/` yourself".
20	 * - the preserve list lived in a person's memory. `config.yaml` was restored every
21	 *   time because it was remembered, not because anything checked.
22	 *
23	 * `self/` mirrors `.github/`, so the deploy became `rm -rf .github`, extract, copy
24	 * `self/` over it. An upstream removal is now ordinary -- the file is not recreated
25	 * -- and the preserve list is a directory rather than a habit.
26	 *
27	 * ## What these tests hold
28	 *
29	 * That the two copies of every overlay file agree, in both directions: the file
30	 * exists in both places, and holds the same bytes.
31	 *
32	 * An overlay entry needs no release to take effect -- it is a copy, not a build --
33	 * so a change to `self/X` belongs in the same pull request as the identical change
34	 * to `.github/X`. This is what turns "remember to change both" into a failing
35	 * check, and it is why an agent improving `config.yaml` cannot half-apply it.
36	 *
37	 * Workflows are the one exception, and the token model is why: GitHub refuses to
38	 * let a GitHub App token write `.github/workflows/**` at all, so an agent can
39	 * change `self/workflows/**` and cannot change the deployed copy. Requiring both
40	 * halves in one pull request would make a workflow change something no agent could
41	 * ever finish. `self/` leads, the deployed copy catches up at the next self-deploy,
42	 * and the test below holds the direction that matters: the deployed copy may not
43	 * be edited on its own.
44	 *
45	 * ## Why there is no "every file in `.github/` is accounted for" test
46	 *
47	 * There was one, and it was wrong. It required every file under `.github/` to
48	 * exist in `dist/.github/` or `self/`, meaning to catch a file that accumulated.
49	 *
50	 * Nothing accumulates any more. The deploy runs `rm -rf .github` first, so a file
51	 * the release stopped shipping is simply not recreated -- which is the whole reason
52	 * `self/` exists. There is nothing left for that test to find.
53	 *
54	 * Worse, it was a false alarm waiting to happen. `dist/` is built from the CURRENT
55	 * `src/`, while `.github/` holds an older release, and the lag between them is
56	 * deliberate: a change to `src/` must not reconfigure the live agents the moment it
57	 * merges, and two breakages reached the running system exactly that way. So merge a
58	 * change that DELETES a file from `src/`, then deploy a release that predates it,
59	 * and the test fails on a correct deploy pull request.
60	 *
61	 * The one case it did cover on its own -- a file added to `.github/` with no
62	 * counterpart in `self/`, which the next deploy would silently remove -- is already
63	 * in front of a person. `.github/**` is in `merge.governed_paths`, so any pull request
64	 * touching it carries the blocker "this pull request changes how agents themselves
65	 * run" and cannot be merged by an agent at all.
66	 *
67	 * These tests likewise do not check that `.github/` matches the current `src/`, for
68	 * the same reason: the lag is the design, not a defect to detect.
69	 */
70	const OVERLAY = "self";
71	const DEPLOYED = ".github";
72	const BUILT = "dist/.github";
73	
74	/**
75	 * The one path `self/` is allowed to shadow, as a path under `.github/` rather
76	 * than as a second spelling of it. It was spelled out, and renaming the layout
77	 * turned the deliberate exception into a violation of the rule it exempts.
78	 */
79	const OVERRIDABLE = relative(DEPLOYED, CONFIG_FILE).replaceAll("\\", "/");
80	
81	function filesUnder(root: string): string[] {
82	  if (!existsSync(root)) return [];
83	  const out: string[] = [];
84	  const walk = (dir: string): void => {
85	    for (const entry of readdirSync(dir)) {
86	      const path = join(dir, entry);
87	      if (statSync(path).isDirectory()) walk(path);
88	      else out.push(relative(root, path).replaceAll("\\", "/"));
89	    }
90	  };
91	  walk(root);
92	  return out.sort();
93	}
94	
95	/**
96	 * Line endings normalised, because this repository is developed on Windows and
97	 * `.github/` is checked out CRLF while `dist/` is written LF by the build. A
98	 * comparison that called every file different would report nothing.
99	 */
100	function body(path: string): string {
101	  return readFileSync(path, "utf8").replaceAll("\r\n", "\n");
102	}
103	
104	/**
105	 * `git`, run in this checkout, returning stdout or `undefined` when it fails.
106	 *
107	 * stderr is swallowed: a fetch that cannot reach the remote is an answer here, not
108	 * something to print. Nothing here stages, commits or writes -- only reads.
109	 */
110	function git(...args: string[]): string | undefined {
111	  const run = spawnSync("git", args, {
112	    encoding: "utf8",
113	    stdio: ["ignore", "pipe", "pipe"],
114	    // `hermeticEnv()` because GIT_DIR and GIT_WORK_TREE OVERRIDE `cwd`: a child
115	    // started here would run against whatever repository the caller pointed it at
116	    // rather than this checkout. `test-hermetic-env.test.ts` requires it of any test
117	    // that spawns git, and it is the same helper the machinery's own scripts use.
118	    env: hermeticEnv(),
119	  });
120	  return run.status === 0 ? run.stdout : undefined;
121	}
122	
123	/**
124	 * The commit this work branched from, or `undefined` when nothing could say.
125	 *
126	 * The same shape as `scan_secrets.ts`. A pull request sets `GITHUB_BASE_REF`, and
127	 * `atomaton-check.yml` checks out shallow, so unshallow before asking for a merge
128	 * base; a repository that is already complete refuses that, which is not a
129	 * failure. A dispatch, and a local run, have no `GITHUB_BASE_REF`: there the base
130	 * is `origin/main`, read from what the checkout already holds rather than fetched,
131	 * so a local run does not reach the network to answer a question about the tree.
132	 *
133	 * Tolerated rather than required, as it is there: no base is not a finding, and
134	 * the caller says so rather than guessing at one.
135	 */
136	function baseCommit(): string | undefined {
137	  const named = (process.env.GITHUB_BASE_REF ?? "").trim();
138	
139	  if (!named) {
140	    for (const ref of ["origin/main", "origin/HEAD"]) {
141	      const base = git("merge-base", ref, "HEAD");
142	      if (base?.trim()) return base.trim();
143	    }
144	    return undefined;
145	  }
146	
147	  git("fetch", "--quiet", "--unshallow", "origin");
148	  if (git("fetch", "--quiet", "origin", named) === undefined) return undefined;
149	  const base = git("merge-base", "FETCH_HEAD", "HEAD");
150	  return base?.trim() ? base.trim() : undefined;
151	}
152	
153	/** The bytes of `path` at `commit`, line endings normalised like `body`. */
154	function bodyAt(commit: string, path: string): string | undefined {
155	  const out = git("show", `${commit}:${path}`);
156	  return out === undefined ? undefined : out.replaceAll("\r\n", "\n");
157	}
