278	 * The skills a tree ships, under the names a run loads them by.
279	 *
280	 * From the filesystem rather than from git, which is the fix and not a preference.
281	 * `ATOMATON_MACHINERY_ROOT` points at `${RUNNER_TEMP}/atomaton-machinery` -- a release
282	 * zip unpacked beside the checkout, and not a git repository at all -- so the
283	 * `git ls-files` this used returned nothing on every run since the section was
284	 * written. Nothing said so: an empty list filtered to an empty list and printed as
285	 * `Every skill has been loaded at least once`, which is why a skill loaded zero times
286	 * could sit in the catalogue unnoticed.
287	 *
288	 * `undefined` when the directory is missing or holds no skill. A deployed tree always
289	 * ships some, so an empty answer is this looking in the wrong place rather than a
290	 * project without any, and the report says it could not check.
291	 */
292	export function skillsUnder(dir: string): string[] | undefined {
293	  let entries: string[];
294	  try {
295	    entries = readdirSync(dir, { recursive: true }).map(String);
296	  } catch {
297	    return undefined;
298	  }
299	  const skills = entries
300	    .filter((entry) => entry.endsWith(".md"))
